from users.validate import validate_email


def import_users(csv_text: str) -> dict:
    """Import users from CSV text (see README)."""
    imported = []
    rejected = []
    seen = set()

    for line_num, line in enumerate(csv_text.splitlines(), start=1):
        if line_num == 1:
            continue
        if line.strip() == "":
            continue
        try:
            name, email = line.split(",", 1)
        except ValueError:
            rejected.append({"line": line_num, "email": line, "reason": "invalid_email"})
            continue

        if not validate_email(email):
            rejected.append({"line": line_num, "email": email, "reason": "invalid_email"})
            continue

        email_lower = email.lower()
        if email_lower in seen:
            rejected.append({"line": line_num, "email": email, "reason": "duplicate"})
            continue

        seen.add(email_lower)
        imported.append({"name": name, "email": email_lower})

    return {"imported": imported, "rejected": rejected}
